	constexpr auto operator |(cwsize_r other) const -> cwsize_r { return value_ | other.value_; }
	constexpr auto operator &(cwsize_r other) const -> cwsize_r { return value_ & other.value_; }
	constexpr auto operator ^(cwsize_r other) const -> cwsize_r { return value_ ^ other.value_; }
